import { neonColors } from "../constants/color";
import { CSSProperties, useState } from "react";
import { IoCloseCircle } from "react-icons/io5";
import { IoCheckmarkCircle } from "react-icons/io5";
import { CreateEditCardProps } from "../types";
import TextInput from "./TextInput";

const CreateEditCard = ({ toggleNewCard,createNewTask }: CreateEditCardProps) => {
  const color = neonColors[0];
  //   const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
  //     useSortable({ id});

  const style: CSSProperties = {
    padding: 8,
    marginBottom: 8,
    borderWidth: 2,
    color: color,
    borderStyle: "solid",
    borderColor: color,
    borderRadius: 10,
    display: "flex",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
  };

  return (
    <div style={style}>
      <div style={{ display: "flex", width: "80%", flexDirection: "column" }}>
        <TextInput largeText={true} color={color} value={title} setValue={setTitle} />
        <TextInput
        largeText={false}
          color={color}
          value={description}
          setValue={setDescription}
        />
      </div>
      <div style={{ display: "flex" }}>
        {title && description ? (
          <IoCheckmarkCircle size={20} onClick={createNewTask} />
        ) : (
          <IoCloseCircle size={20} onClick={toggleNewCard} />
        )}
      </div>
    </div>
  );
};

export default CreateEditCard;
